def assemble():
    families=[]
    for i, c in enumerate(CASES, 1):
        fid=f'B{i:02d}'
        rid=lambda n:f'{fid}R{n:02d}'
        records=[]
        for j, x in enumerate(c['records'], 1):
            body=f"This {x['title'].lower()} is issued by the {x['authority'].lower()} for {x['scope']}. {x['seed']} {c['context']}"
            if fid=='B01' and j==2:
                body=body.replace('There were no other excursions that day.', 'There were no other excursions in the completed logger run.')
            if fid=='B14' and j==2:
                body=body.replace('Hazel has no preceding shift that week.', 'Hazel has no shift in the preceding seven days.')
            authored=x['date'] or DATES[j-1]
            if j in DATE_OVERRIDES.get(fid,{}):
                authored='2026-'+DATE_OVERRIDES[fid][j]+':00Z'
            records.append(dict(id=rid(j),kind='source',revision=x['revision'],
                authored_at=authored,title=x['title'],scope=x['scope'],body=body,
                links=[rid(n) for n in x['links']],supersedes=[rid(n) for n in x['supersedes']],incorporates=[]))
        derived_body='This saved view is a secondary desk summary, not a new original authorization. '+SAVED_VIEWS[fid]+' '+c['context']
        records.append(dict(id=rid(10),kind='derived',revision=2,authored_at=DERIVED_DATES.get(fid,'2026-10-10T18:00:00Z'),
            title=c['name']+' saved view',scope='all',
            body=derived_body,
            links=[rid(n) for n in c['ledger']],supersedes=[],
            incorporates=[dict(id=rid(n),revision=c['records'][n-1]['revision']) for n in c['ledger']]))
        tasks=[]
        for j,x in enumerate(c['tasks'],1):
            public_status=' Status values: ready means a resolved decision or computed result; hold means the requested action awaits required evidence or authority.'
            tasks.append(dict(id=f'{fid}Q{j}',query=x['query']+public_status,answer_keys=list(x['answer']),
                              expected=dict(status=x['status'],answer=x['answer']),
                              critical_keys=list(x['answer']),
                              evidence_sets=[[rid(n) for n in s] for s in x['evidence']]))
        families.append(dict(id=fid,name=c['name'],domain=c['domain'],aliases=c['aliases'],
                             stratum=c['stratum'],records=records,tasks=tasks))
    return dict(schema_version=1,author='author-b',families=families)

def check(data):
    allowed={'late_correction','scope_exception','unresolved_conflict','missing_prerequisite',
             'unicode_alias','late_import','missing_edge','wrong_ledger'}
    assert data['schema_version']==1 and data['author']=='author-b'
    assert len(data['families'])==24
    assert all(sum(f['stratum']==s for f in data['families'])==3 for s in allowed)
    all_ids=set()
    record_by_id={}
    tasks=[]
    for f in data['families']:
        assert f['id'] not in all_ids
        all_ids.add(f['id'])
        assert f['stratum'] in allowed and len(f['aliases'])==2
        assert 10<=len(f['records'])<=14
        assert sum(r['kind']=='source' for r in f['records'])>=8
        assert any(r['kind']=='derived' for r in f['records'])
        for rec in f['records']:
            assert rec['id'] not in all_ids
            all_ids.add(rec['id']);record_by_id[rec['id']]=rec
            assert rec['kind'] in {'source','derived'} and rec['revision']>=1
            assert rec['authored_at'].startswith('2026-') and rec['authored_at'].endswith('Z')
            count=len(rec['body'].split())
            assert 70<=count<=130,(rec['id'],count)
            if rec['kind']=='source': assert rec['incorporates']==[]
        assert len(f['tasks'])==2
        assert any(any(3<=len(s)<=5 for s in t['evidence_sets']) for t in f['tasks'])
        for task in f['tasks']:
            assert task['id'] not in all_ids
            all_ids.add(task['id']);tasks.append(task)
            ans=task['expected']['answer']
            assert task['expected']['status'] in {'ready','hold'}
            assert set(task['answer_keys'])==set(ans)==set(task['critical_keys'])
            assert all(v is None or isinstance(v,(str,int,float,bool,list)) for v in ans.values())
            assert all(not isinstance(v,dict) for v in ans.values())
            if task['expected']['status']=='hold':
                assert any(v is None for v in ans.values()),task['id']
                assert isinstance(ans.get('unresolved'),list) and ans['unresolved'],task['id']
    assert len(tasks)==48
    for rec in record_by_id.values():
        for ref in rec['links']+rec['supersedes']:
            assert ref in record_by_id,(rec['id'],ref)
        for ref in rec['incorporates']:
            assert ref['id'] in record_by_id
            original=record_by_id[ref['id']]
            assert original['kind']=='source'
            assert original['revision']==ref['revision']
    for t in tasks:
        assert t['evidence_sets']
        for ev in t['evidence_sets']:
            assert len(ev)==len(set(ev))
            for ref in ev:
                assert ref in record_by_id and record_by_id[ref]['kind']=='source',(t['id'],ref)
        assert not any(rid in t['query'] for rid in record_by_id),t['id']
    unicode_families=sum(any(ord(ch)>127 for ch in json.dumps(f,ensure_ascii=False)) for f in data['families'])
    assert unicode_families>=6,unicode_families
    word_counts=[len(r['body'].split()) for r in record_by_id.values()]
    return dict(families=len(data['families']),tasks=len(tasks),records=len(record_by_id),
                original_records=sum(r['kind']=='source' for r in record_by_id.values()),
                unicode_families=unicode_families,min_words=min(word_counts),max_words=max(word_counts),
                strata={s:sum(f['stratum']==s for f in data['families']) for s in sorted(allowed)})

if __name__=='__main__':
    data=assemble()
    receipt=check(data)
    OUT.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    assert json.loads(OUT.read_text(encoding='utf-8'))==data
    print(json.dumps(receipt,indent=2))
